### ✅ Updated & Improved Version with Multiple Cache Backends

```python
import pickle
from abc import ABC, abstractmethod
from typing import Any, Optional

# Abstract base class for cache backends
class CacheBackend(ABC):
    @abstractmethod
    def get(self, key: str) -> Optional[Any]:
        pass

    @abstractmethod
    def set(self, key: str, value: Any, expire: int = 0) -> None:
        pass

    @abstractmethod
    def delete(self, key: str) -> None:
        pass


# Redis Backend (using redis-py)
try:
    import redis
    class RedisCache(CacheBackend):
        def __init__(self, host: str = "localhost", port: int = 6379, db: int = 0, password: str = None):
            self.client = redis.StrictRedis(
                host=host,
                port=port,
                db=db,
                password=password,
                decode_responses=True
            )

        def get(self, key: str) -> Optional[Any]:
            return self.client.get(key)

        def set(self, key: str, value: Any, expire: int = 0) -> None:
            if expire > 0:
                self.client.setex(key, expire, pickle.dumps(value))
            else:
                self.client.set(key, pickle.dumps(value))

        def delete(self, key: str) -> None:
            self.client.delete(key)

except ImportError:
    RedisCache = None  # Fallback if redis-py not installed


# Memcached Backend (using pymemcache)
try:
    import pymemcache.client
    class MemcachedCache(CacheBackend):
        def __init__(self, server: str = "127.0.0.1:11211"):
            self.client = pymemcache.client.Client(server)

        def get(self, key: str) -> Optional[Any]:
            value = self.client.get(key)
            return pickle.loads(value) if value else None

        def set(self, key: str, value: Any, expire: int = 0) -> None:
            self.client.set(key, pickle.dumps(value), expire=expire)

        def delete(self, key: str) -> None:
            self.client.delete(key)

except ImportError:
    MemcachedCache = None  # Fallback if pymemcache not installed


# In-memory fallback (for development or no backend)
class InMemoryCache(CacheBackend):
    def __init__(self):
        self.data = {}

    def get(self, key: str) -> Optional[Any]:
        return self.data.get(key)

    def set(self, key: str, value: Any, expire: int = 0) -> None:
        self.data[key] = value

    def delete(self, key: str) -> None:
        if key in self.data:
            del self.data[key]


# GameCache class with backend support
class GameCache:
    def __init__(self, cache_backend: str = "inmemory", **backend_kwargs):
        self.cache_backend = cache_backend.lower()
        self.cache_backend_instance = None

        # Initialize backend based on type
        if self.cache_backend == "redis":
            if RedisCache is None:
                raise ImportError("redis-py is required for Redis backend. Install with: pip install redis")
            self.cache_backend_instance = RedisCache(**backend_kwargs)
        elif self.cache_backend == "memcached":
            if MemcachedCache is None:
                raise ImportError("pymemcache is required for Memcached backend. Install with: pip install pymemcache")
            self.cache_backend_instance = MemcachedCache(**backend_kwargs)
        elif self.cache_backend == "inmemory":
            self.cache_backend_instance = InMemoryCache()
        else:
            raise ValueError(f"Unknown cache backend: {self.cache_backend}")

        # Local cache for fast access (optional: use as a local buffer)
        self.local_cache = {}

    def get_player_profile(self, player_id: str) -> Optional[Any]:
        key = f"profile_{player_id}"
        if key in self.local_cache:
            return self.local_cache[key]

        # Fetch from backend
        profile = self.cache_backend_instance.get(key)
        if profile is not None:
            self.local_cache[key] = profile
            return profile
        return None

    def get_game_progress(self, game_id: str) -> Optional[Any]:
        key = f"progress_{game_id}"
        if key in self.local_cache:
            return self.local_cache[key]

        progress = self.cache_backend_instance.get(key)
        if progress is not None:
            self.local_cache[key] = progress
            return progress
        return None

    def set_player_profile(self, player_id: str, profile: Any) -> None:
        key = f"profile_{player_id}"
        self.cache_backend_instance.set(key, profile)
        self.local_cache[key] = profile

    def set_game_progress(self, game_id: str, progress: Any) -> None:
        key = f"progress_{game_id}"
        self.cache_backend_instance.set(key, progress)
        self.local_cache[key] = progress

    def clear(self) -> None:
        self.local_cache.clear()
        self.cache_backend_instance.delete(f"profile_*")  # Optional: clear all profiles
        self.cache_backend_instance.delete(f"progress_*")  # Optional: clear all progress


