import unittest

class TestPlaylistSorting(unittest.TestCase):
    def setUp(self):
        self.playlist = ["song1", "song2", "song3"]
        self.popularity = {"song1": 10, "song2": 5, "song3": 8}

    def test_sort_list_by_popularity(self):
        sorted_playlist = sorted(self.playlist, key=lambda x: self.popularity[x], reverse=True)
