    def test_sort_list_reversed(self):
        # Test that sorting in reverse order (descending popularity) works correctly
        sorted_playlist = sorted(self.playlist, key=lambda x: self.popularity[x], reverse=True)
        self.assertEqual(sorted_playlist, ["song1", "song3", "song2"])

        # Additional test: verify that the original playlist remains unchanged
        # (since sorted() creates a new list)
        self.assertEqual(self.playlist, ["song1", "song2", "song3"])

if __name__ == '__main__':
    unittest.main()
